import{_ as t,c as s,o as i,j as e,a as r}from"./chunks/framework.Dnh4IO1K.js";const f=JSON.parse('{"title":"卷四·28","description":"易小帖 - 卷四·28","frontmatter":{"title":"卷四·28","description":"易小帖 - 卷四·28"},"headers":[],"relativePath":"zh/classics/yixiaotie/122.md","filePath":"zh/classics/yixiaotie/122.md"}'),o={name:"zh/classics/yixiaotie/122.md"};function c(n,a,l,d,p,m){return i(),s("div",null,[...a[0]||(a[0]=[e("h1",{id:"卷四·28",tabindex:"-1"},[r("卷四·28 "),e("a",{class:"header-anchor",href:"#卷四·28","aria-label":"Permalink to “卷四·28”"},"​")],-1),e("p",null,"「用九，見羣龍無首，吉。」與上九「亢龍有悔」合作一節。《春秋傳》蔡墨之對原是如此。後儒不解其義，分作二節。予既已辨之乾卦中矣，但又有說未盡者。予謂：乾之夬曰「亢龍有悔」，此固乾上九爻也，即之坤曰「見羣龍無首吉」，亦上九爻，何也？天下無非爻而可雲變者，既能變坤，則非上九不可也。或曰：不然，乾之夬則乾上爻變，故曰上九。若之坤，則六爻俱變，何曾止上爻變而曰此上爻詞也？則予又曰：不然。夫乾之變夬，何曾止上爻變乎。乾初變為姤，二變為同人，三變為履，四變為小畜，五變為大有，亦五爻皆變，而後變夬，特其變夬時，則已前五爻不必皆變也。但以全乾變上爻，而即曰之夬，故曰乾之夬也。若乾之坤，則亦未嘗以上爻變也，但十闢所謂自姤至剝，皆陰消乾之卦，從乾起見，故皆以乾名。如乾初變為姤，二變為遯，三變為否，四變為觀，五變為剝，而後六變而至坤。則雖其變，坤不止上爻，且是剝之坤非乾之坤，而因乾而變則皆乾之變。其遇為乾而所之為坤，是非剝之上爻，乾之上爻也。然則之坤亦上九矣。時予註易成而客仍有疑之者，故復著此。",-1)])])}const h=t(o,[["render",c]]);export{f as __pageData,h as default};
